package org.codex.nfsugpreview;
import java.nio.*;import java.util.*;
/** Immutable original sky-copy inputs and phase sampling. No simulation clock. */
final class NativeSky {
 final long epoch,refresh,angle,source,origin,destination;final int center;private final byte[] indices;
 NativeSky(byte[] data){if(data==null||data.length!=15192)throw new IllegalArgumentException("sky size");ByteBuffer b=ByteBuffer.wrap(data).order(ByteOrder.LITTLE_ENDIAN);epoch=b.getLong(8);refresh=u(b.getInt(16));angle=u(b.getInt(20));source=u(b.getInt(32));origin=u(b.getInt(36));destination=u(b.getInt(40));center=b.getInt(48);long offset=((((angle&16383)*240)>>12)%240-center)&~1L;
 if(b.getInt(0)!=0x4b53464e||b.getInt(4)!=1||epoch==0||b.getInt(24)!=240||b.getInt(28)!=64||b.getInt(44)!=15136||b.getInt(52)!=0||center<-32768||center>32767||origin<0x08000000L||origin>0x0a000000L-15376||(destination!=0x06002940L&&destination!=0x0600c940L)||source!=((origin+offset)&0xffffffffL))throw new IllegalArgumentException("sky header");indices=Arrays.copyOfRange(data,56,data.length);}
 private static long u(int x){return x&0xffffffffL;}
 private void verify(byte[] asset){long offset=source-origin;if(asset==null||asset.length!=15376||center!=0||offset<0||offset>238)throw new IllegalArgumentException("sky asset");for(int i=0;i<15136;i++)if(asset[(int)offset+i]!=indices[i])throw new IllegalArgumentException("sky source bytes");}
 static final class Sample {final double phase,weight;final int lowerOffset,upperOffset;final boolean exact;private final byte[] lower,upper;Sample(byte[] lo,byte[] hi,double p,double w,int l,int h,boolean e){lower=lo.clone();upper=hi.clone();phase=p;weight=w;lowerOffset=l;upperOffset=h;exact=e;}ByteBuffer lower(){return ByteBuffer.wrap(lower).asReadOnlyBuffer();}ByteBuffer upper(){return ByteBuffer.wrap(upper).asReadOnlyBuffer();}}
 Sample sample(NativeSky newer,byte[] asset,double alpha,int mode){if(newer==null||mode<0||mode>1||!Double.isFinite(alpha)||alpha<0||alpha>1||epoch!=newer.epoch||refresh>newer.refresh||origin!=newer.origin)throw new IllegalArgumentException("sky pair");verify(asset);newer.verify(asset);if(refresh==newer.refresh&&(angle!=newer.angle||source!=newer.source||!Arrays.equals(indices,newer.indices)))throw new IllegalArgumentException("sky same refresh");int delta=(int)((newer.angle-angle+8192)&16383)-8192;double expected=delta*(240.0/4096);if(Math.abs(expected)>=120)throw new IllegalArgumentException("sky ambiguous travel");if(mode==0&&(alpha==0||alpha==1)){NativeSky chosen=alpha==1?newer:this;return new Sample(chosen.indices,chosen.indices,chosen.source-chosen.origin,0,0,0,true);}double phase;if(mode==1){double a=alpha==1?(newer.angle&16383):(angle&16383)+delta*alpha;phase=a*(240.0/4096);}else{double lo=source-origin,hi=newer.source-newer.origin;phase=lo+(hi-lo+240*Math.rint((expected-(hi-lo))/240))*alpha;}phase%=240;if(phase<0)phase+=240;int lo=(int)Math.floor(phase),hi=(lo+1)%240;return new Sample(Arrays.copyOfRange(asset,lo,lo+15136),Arrays.copyOfRange(asset,hi,hi+15136),phase,phase-lo,lo,hi,false);}
}
